from math import isqrt


def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number iff it has exactly two distinct
    prime factors, and each prime occurs to an even exponent in N. Thus N is
    the square of an integer with exactly two distinct prime factors.
    """
    limit = isqrt(a)
    distinct_factors = bytearray(limit + 1)

    # Count distinct prime divisors for every possible square root.
    for p in range(2, limit + 1):
        if distinct_factors[p] == 0:
            for multiple in range(p, limit + 1, p):
                distinct_factors[multiple] += 1

    for root in range(limit, 1, -1):
        if distinct_factors[root] == 2:
            return root * root

    # The input lower bound (36) guarantees that 6**2 is available.
    raise ValueError("no 400 number exists below the given bound")

